parameters.jsCode:
// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const url  = site + '/invite/' + encodeURIComponent(d.slug);
const dash = site + '/dashboard/' + encodeURIComponent(d.event_id);
const archiveCta = site + '/pricing#archive';

const memories = `<div style="margin:0 0 20px;">
    ${stat('Views', d.total_views)}${stat('Attended', d.rsvp_yes)}
    ${stat('Blessings', d.blessings)}${stat('Photos', d.photos)}
  </div>`;

const steps = {
  expiry_7d: {
    subject: 'Your invitation comes down in a week',
    heading: 'A week left',
    body: `<p style="margin:0 0 16px;">Hi ${esc(d.owner_name)}, <strong>${esc(d.title)}</strong> comes down on ${esc(d.expires_on)} \u2014 a week from now.</p>
           ${memories}
           <p style="margin:0;">If you want to keep the link working \u2014 the photos, the blessings, the guest list \u2014 you can archive it permanently. The URL never changes, so every message you already sent keeps working.</p>`,
    cta: 'Keep it permanently', href: archiveCta,
  },
  expiry_1d: {
    subject: 'Your invitation comes down tomorrow',
    heading: 'Tomorrow',
    body: `<p style="margin:0 0 16px;">Hi ${esc(d.owner_name)}, this is the last reminder: <strong>${esc(d.title)}</strong> comes down on ${esc(d.expires_on)}.</p>
           ${memories}
           <p style="margin:0;">Archiving keeps the same link alive permanently. After tomorrow you can still archive it, but the link will have been dark in the meantime.</p>`,
    cta: 'Keep it permanently', href: archiveCta,
  },
  archive_offer: {
    subject: 'Keep ' + (d.title || 'your invitation') + ' forever',
    heading: 'Keep it forever',
    body: `<p style="margin:0 0 16px;">Hi ${esc(d.owner_name)}, it has been about a month since ${esc(d.event_date)}. Here is what ${esc(d.title)} did:</p>
           ${memories}
           <p style="margin:0 0 14px;">${Number(d.blessings) > 0
             ? '<strong>' + d.blessings + ' people</strong> left you a message on it. Those are worth keeping.'
             : 'Everything is still there \u2014 the photos, the story, the guest list.'}</p>
           <p style="margin:0;">Archiving keeps the same link working permanently, on the same URL you already shared.</p>`,
    cta: 'Archive my invitation', href: archiveCta,
  },
};

const step = steps[d.kind];
return { json: {
  dedupe_key: d.dedupe_key,
  to: d.owner_email,
  stored: {
    event_id: d.event_id, slug: d.slug, title: d.title, kind: d.kind,
    expires_on: d.expires_on, days_to_expiry: d.days_to_expiry,
    total_views: d.total_views, blessings: d.blessings, dedupe_key: d.dedupe_key,
    subject: step.subject,
    html: shell(step.heading, step.body, step.cta, step.href,
      `Your invitation: <a href="${url}" style="color:#8a7d7a;">${esc(d.slug)}</a> \u00b7 <a href="${dash}" style="color:#8a7d7a;">dashboard</a> \u00b7 <a href="${unsub('reminder')}" style="color:#8a7d7a;">unsubscribe</a>`),
    text: step.heading + '\n\n' + d.title + '\nExpires ' + d.expires_on + '\n'
      + d.total_views + ' views, ' + d.rsvp_yes + ' attended, ' + d.blessings + ' blessings\n\n'
      + step.cta + ': ' + step.href,
    unsubscribe: unsub('reminder'),
  },
} };

parameters.jsonBody:
={{ JSON.stringify({
  from: $env.AMANTRIKA_EMAIL_FROM,
  to: [ $json.recipient ],
  subject: $json.payload.subject,
  html: $json.payload.html,
  text: $json.payload.text,
  headers: $json.payload.unsubscribe
    ? { 'List-Unsubscribe': '<' + $json.payload.unsubscribe + '>',
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
    : {}
}) }}
